export function buildImageSeries({text='',entries,shared='',refs=[]}){const parts=(Array.isArray(entries)?entries:text.split(/\r?\n/)).map(x=>x.trim()).filter(Boolean);if(!parts.length)throw Error('Nhập ít nhất một prompt cho bộ ảnh. Mỗi ô là một ảnh.');if(parts.length>30)throw Error('Mỗi bộ tối đa 30 prompt. Hãy chia thành nhiều bộ.');const lock='SERIES CONTINUITY: Create one coherent image series. Keep the same character identity, facial structure, hair, wardrobe, product design, materials, palette and visual style across every image unless a scene explicitly requests a change. Use only the supplied input images as the source of identity and design. Each output is one standalone image, never a contact sheet or collage.\nSHARED INPUTS:\n'+refs.map((r,i)=>'Reference '+(i+1)+' = @'+r.tag).join('\n')+'\nSHARED BRIEF:\n'+shared.trim();return parts.map((p,i)=>lock+'\nIMAGE '+(i+1)+' OF '+parts.length+' — SCENE PROMPT:\n'+p)}
